import type { App, VNode } from 'vue'
import PrimeVue from 'primevue/config'
import ContextMenu from 'primevue/contextmenu'
import Menu from 'primevue/menu'
import Portal from 'primevue/portal'
import { createCommentVNode, h, renderSlot, Teleport } from 'vue'

const LAYER_ATTR = 'data-wippy-overlay-layer'

/** A per-overlay layer div carrying its overlay's trigger anchor-name for the observer. */
interface LayerWithAnchor extends HTMLElement { __wippyAnchorName?: string }

/**
 * Client (browser) guard, equivalent to `@primeuix/utils`' `isClient` — inlined so
 * this plugin (which ships as raw `.ts` that every consumer typechecks) takes no
 * dependency on `@primeuix/utils`, which is only a transitive dep of `primevue` and
 * is not guaranteed to resolve at the `/dom` subpath in a consumer's build.
 */
function isClient(): boolean {
  return typeof window !== 'undefined' && typeof window.document !== 'undefined'
}

/**
 * The browser Popover API (and thus the top layer) is available.
 *
 * We promote each overlay's own layer into the document's **top layer**
 * so overlays escape every ancestor stacking context in that document — nested
 * shadow hosts, sticky toolbars, a later sibling's positive `z-index` — for BOTH
 * paint and hit-testing, with no `z-index` anywhere. The overlay stays inside its
 * owning shadow root, so module-local CSS and inherited `--p-*` tokens are
 * untouched (inheritance follows the flat tree, not the top-layer position). Widely
 * available in modern engines (Chrome/Edge 114+, Firefox 125+, Safari 17+); older
 * engines fall back to the pinned-layer-only behavior below (stacking imperfect,
 * everything else unchanged). Evaluated lazily so SSR never touches `HTMLElement`.
 */
function supportsTopLayer(): boolean {
  return (
    isClient()
    && typeof HTMLElement !== 'undefined'
    && Object.hasOwn(HTMLElement.prototype, 'popover')
  )
}

/**
 * CSS anchor positioning is available (S2). Implies the top layer. Lets a promoted
 * overlay anchor to its trigger with pure CSS — no JS reposition loop — for the
 * SELF-ANCHORED overlay families whose PrimeVue panel aligns to the component root,
 * which is the Portal placeholder's DOM parent (`Select`, `MultiSelect`, `TreeSelect`,
 * `CascadeSelect` — live-verified on `Select`; the others share the same align-to-root
 * shape. `AutoComplete` is excluded — see {@link SELF_ANCHORED_OVERLAY}). S2 requires
 * the anchor, placement, fallback and sizing features checked below. Engines that lack
 * a required feature, and menus / popovers that align to an arbitrary caller-supplied
 * target, keep S1's pinned-layer positioning. S2 runs
 * only behind this feature gate, and `applyAnchor` restores PrimeVue's own inline positioning
 * verbatim (S1) if a promoted overlay can't enter the top layer — so the stacking fix always
 * holds and positioning never regresses.
 * (Tooltips never reach this plugin at all: PrimeVue's Tooltip is a directive that
 * appends to `document.body`, outside `primevue/portal`.)
 */
function supportsAnchor(): boolean {
  return (
    supportsTopLayer()
    && typeof CSS !== 'undefined'
    && typeof CSS.supports === 'function'
    && CSS.supports('anchor-name: --a')
    && CSS.supports('position-area', 'bottom span-right')
    && CSS.supports('position-try-fallbacks', 'flip-block')
    && CSS.supports('min-width', 'min(anchor-size(width), 100vw)')
    && CSS.supports('max-width', 'stretch')
  )
}

/**
 * Overlay classes whose panel aligns to the COMPONENT ROOT — the Portal placeholder's
 * DOM parent — so a unique `anchor-name` stamped on that root is the correct CSS anchor.
 * `AutoComplete` is deliberately EXCLUDED: it aligns its panel to an inner element
 * (`$refs.focusInput`/`multiContainer`), not the root, so anchoring to the root would
 * offset it; it keeps S1 (PrimeVue's own positioning against the correct element).
 */
const SELF_ANCHORED_OVERLAY = /\bp-(?:select|multiselect|treeselect|cascadeselect)-overlay\b/

/** Sequential id for per-trigger `anchor-name`s — collision-free and readable (Math.random isn't). */
let anchorSeq = 0

/** Per-overlay observer that re-applies S2 styles when PrimeVue re-aligns the overlay. */
const anchorStyleObservers = new WeakMap<HTMLElement, MutationObserver>()

/** Write the S2 positioning declarations that make the overlay a fixed, anchored popover. */
function setAnchorStyles(overlay: HTMLElement, anchorName: string): void {
  const s = overlay.style
  // Own `position:fixed` top-layer popover: promotion needs a popover, and `fixed` gives
  // the viewport containing block that `anchor()` and the top layer resolve against
  // (instead of the pinned 0×0 layer). PrimeVue's theme border/background/padding still
  // win over the UA `[popover]` box (author > UA); we override only positioning.
  s.setProperty('position', 'fixed', 'important')
  s.setProperty('inset', 'auto', 'important')
  s.setProperty('margin', '0', 'important')
  s.setProperty('position-anchor', anchorName)
  // Flip the placement area rather than important inset declarations. Important
  // anchor() offsets override the fallback's offsets and leave the panel offscreen.
  s.setProperty('position-area', 'bottom span-right')
  s.setProperty('position-try-fallbacks', 'flip-block, flip-inline, flip-block flip-inline')
  s.setProperty('min-width', 'min(anchor-size(width), 100vw)', 'important')
  s.setProperty('max-width', 'stretch', 'important')
}

/**
 * S2: make a self-anchored overlay its own fixed, CSS-anchored top-layer popover (no-op
 * for other overlays — they keep S1).
 *
 * PrimeVue keeps RE-aligning the overlay while it is open (`alignOverlay()` on every
 * filter keystroke), plain-writing `top`/`margin` on the same
 * inline `style`. Since an inline style has ONE slot per property, that plain write
 * REPLACES our `!important` value+priority — so a one-shot write is not durable. We
 * therefore also watch the overlay's own `style` and re-apply whenever PrimeVue clobbers
 * it; checking the expected neutral offsets and margin makes the re-apply idempotent.
 * The observer is released when the overlay leaves its layer ({@link releaseAnchor}).
 */
function applyAnchor(overlay: HTMLElement, anchorName: string): void {
  if (!SELF_ANCHORED_OVERLAY.test(overlay.className))
    return
  const restore = overlay.style.cssText
  setAnchorStyles(overlay, anchorName)
  if (overlay.getAttribute('popover') !== 'manual')
    overlay.setAttribute('popover', 'manual')
  try {
    if (!overlay.matches(':popover-open'))
      overlay.showPopover()
  }
  catch { /* not connected / already open */ }
  if (!overlay.matches(':popover-open')) {
    // Promotion didn't take — restore PrimeVue's ORIGINAL inline styles verbatim (rather
    // than clearing the S2 properties piecemeal, which would also wipe the top/left/margin
    // PrimeVue computed for the overlay), so it degrades to a correctly-positioned S1
    // overlay inside the layer.
    overlay.removeAttribute('popover')
    overlay.style.cssText = restore
    return
  }
  if (!anchorStyleObservers.has(overlay)) {
    const obs = new MutationObserver(() => {
      const s = overlay.style
      if (s.top !== 'auto' || s.left !== 'auto' || s.margin !== '0px'
        || s.getPropertyPriority('top') !== 'important'
        || s.getPropertyPriority('left') !== 'important'
        || s.getPropertyPriority('margin') !== 'important'
        || s.getPropertyPriority('min-width') !== 'important'
        || s.maxWidth !== 'stretch'
        || s.getPropertyPriority('max-width') !== 'important') {
        setAnchorStyles(overlay, anchorName)
      }
    })
    obs.observe(overlay, { attributes: true, attributeFilter: ['style'] })
    anchorStyleObservers.set(overlay, obs)
  }
}

/** Detach an overlay's S2 style observer once it leaves its layer (closed) or unmounts. */
function releaseAnchor(overlay: HTMLElement): void {
  const obs = anchorStyleObservers.get(overlay)
  if (obs) {
    obs.disconnect()
    anchorStyleObservers.delete(overlay)
  }
}

/** The `ShadowRoot` a node lives in, or null (light DOM). */
function shadowRootOf(el: Node | null): ShadowRoot | null {
  const root = el && typeof el.getRootNode === 'function' ? el.getRootNode() : null
  return root instanceof ShadowRoot ? root : null
}

/**
 * Pin `layer` (a `position: fixed` element) so its viewport origin is exactly
 * `(-scrollX, -scrollY)` — i.e. document coordinate `(0,0)` maps to the layer's
 * top-left corner.
 *
 * PrimeVue's `absolutePosition` writes DOCUMENT coordinates to an overlay
 * (`trigger.getBoundingClientRect()` + window scroll). The overlay is
 * `position: absolute`, so those coordinates resolve against this layer. Placing
 * the layer at `(-scrollX, -scrollY)` makes an absolute child at document coord D
 * render at viewport `D - scroll` — the correct on-screen spot.
 *
 * We MEASURE instead of assuming "fixed == viewport origin": a fixed element's
 * containing block is the nearest ancestor with `transform` / `filter` /
 * `perspective` / `will-change` / `contain` (extremely common — `translateZ(0)`
 * GPU hints, slide animations, virtualized lists), NOT necessarily the viewport.
 * Reading the rect at `top:0;left:0` yields that containing block's viewport
 * origin; we then offset by it plus the scroll. This holds for any
 * TRANSLATION-only containing block and any window scroll.
 *
 * Residuals (documented) — these apply ONLY to the degraded, non-top-layer fallback
 * (older engines, {@link supportsTopLayer} false). Once the layer is promoted (the
 * primary path), its containing block is unconditionally the viewport, so the measured
 * rect at `top:0;left:0` is (0,0) and none of these arise:
 *  - SCALE / ROTATE / SKEW containing block: compensating via CSS `top`/`left`
 *    only cancels the containing block's translation, not a non-identity linear
 *    transform, so a `scale()`/`rotate()`/`skew()` ancestor mispositions the
 *    overlay (by `(s-1)·distance` under `scale(s)`). Rare for a shadow-host
 *    ancestor; a full fix would need the ancestor's transform matrix. Translation
 *    (`translate`, `translateZ(0)`) is the common case and is handled.
 *  - CLIPPING: an ancestor that both establishes the fixed containing block AND
 *    clips (`transform`/`contain`/`will-change` + `overflow != visible`, or
 *    `contain: paint/strict/content`, or `overflow: clip`) can still clip an
 *    overlay that extends beyond its box — intrinsic to staying in the shadow root.
 *  - ANIMATING ancestor: if the containing block MOVES between resyncs (a
 *    transform animating while an overlay is open) the overlay lags until the
 *    next scroll/resize.
 *  - `position: fixed` self-positioning overlays (Toast) resolve against a
 *    transformed containing block, not the viewport, so they are offset under such
 *    an ancestor (their own fixed CSS, not `absolutePosition`, is unaffected by the
 *    layer). Wippy bridges toasts to the host, so this is not hit in practice.
 */
function syncLayer(layer: HTMLElement): void {
  layer.style.top = '0px'
  layer.style.left = '0px'
  const rect = layer.getBoundingClientRect()
  layer.style.top = `${-window.scrollY - rect.top}px`
  layer.style.left = `${-window.scrollX - rect.left}px`
}

// A SINGLE viewport-driven resync loop shared by every per-overlay layer — not a
// listener pair per layer. Layers are removed by `teardownOverlayLayer` (on unmount or a
// switch to inline); this loop is the backstop that also prunes any layer whose shadow
// root detached out from under it (e.g. a `view.component` torn down), so a cycle leaks
// no window listener, observer, or detached subtree.
const activeLayers = new Set<HTMLElement>()
const layerObservers = new WeakMap<HTMLElement, MutationObserver>()
let viewportListenersAttached = false
let viewportSyncScheduled = false

function syncActiveLayers(): void {
  viewportSyncScheduled = false
  for (const layer of activeLayers) {
    if (!layer.isConnected) {
      // Backstop for a layer whose shadow root detached without the Portal's `unmounted`
      // running: release any overlay's S2 observer too (symmetry with `unmounted`).
      for (const child of Array.from(layer.children)) {
        if (child instanceof HTMLElement)
          releaseAnchor(child)
      }
      activeLayers.delete(layer)
      layerObservers.get(layer)?.disconnect()
      continue
    }
    if (layer.childElementCount > 0)
      syncLayer(layer)
  }
}

function onViewportChange(): void {
  if (viewportSyncScheduled)
    return
  viewportSyncScheduled = true
  requestAnimationFrame(syncActiveLayers)
}

/**
 * Create a fresh per-OVERLAY layer (one per Portal instance, NOT shared per shadow root),
 * pinned to viewport origin and kept in sync as its overlay opens (a per-layer
 * `MutationObserver`) and as the page scrolls/resizes (the one shared listener pair over
 * {@link activeLayers}). One overlay per layer keeps S2 anchor routing unambiguous even
 * for components that open several overlays at once; {@link teardownOverlayLayer} removes
 * it on unmount or a switch to inline.
 */
function createLayer(root: ShadowRoot): HTMLElement {
  const layer = document.createElement('div')
  layer.setAttribute(LAYER_ATTR, '')
  const topLayer = supportsTopLayer()
  // Inline reset of the UA `[popover]` styling — scoped to this one private element,
  // NEVER a global rule that could leak across modules. A shown popover gets the UA
  // box (position:fixed; inset:0; margin:auto; width/height:fit-content; border:solid;
  // padding; background:Canvas; color:CanvasText). Left unreset, our empty 0×0 layer
  // paints as a small white BORDERED box centered in the viewport (margin:auto + inset:0),
  // and recolors the teleported overlay's text through inheritance. We zero every UA-set
  // box property (including margin, so our syncLayer-owned top/left position it at origin);
  // `color:inherit` restores the shadow-host inheritance chain for the teleported
  // overlay; `overflow:visible` lets the absolutely-positioned overlay paint outside
  // the 0×0 box. `!important` guards against a non-compliant theme's `[popover]` rule.
  // `top`/`left` are deliberately OMITTED and left author-normal — syncLayer owns them,
  // and its plain setProperty must keep winning (so we also never set `inset`, whose
  // longhands would otherwise fight syncLayer's top/left).
  layer.style.cssText = topLayer
    ? 'position:fixed;width:0 !important;height:0 !important;margin:0 !important;border:0 !important;padding:0 !important;background:transparent !important;color:inherit !important;overflow:visible !important;'
    : 'position:fixed;top:0;left:0;width:0;height:0;'
  if (topLayer)
    layer.setAttribute('popover', 'manual')
  root.appendChild(layer)
  if (topLayer) {
    // Enter the top layer. `manual` never light-dismisses, so PrimeVue stays the sole
    // controller of open/close, Escape, and outside-click; focus stays untouched too, since
    // neither the bare layer div nor PrimeVue's overlay markup carries an `autofocus` target
    // for the popover focusing steps to act on (those run regardless of popover type).
    // `teardownOverlayLayer` removes the layer (on unmount or a switch to inline),
    // evicting it from the top layer; syncActiveLayers is the backstop if the shadow root
    // detaches first.
    try {
      layer.showPopover()
    }
    catch {
      // showPopover only throws if disconnected/already-open; the degrade below covers
      // a layer that ended up not promoted regardless of throw-vs-silent-noop.
    }
    if (!layer.matches(':popover-open')) {
      // Promotion did not take. NEVER leave `popover` set on a not-open element: the
      // UA rule `[popover]:not(:popover-open){display:none}` would hide the layer AND
      // every overlay teleported into it — silently worse than the original bug.
      // Degrade cleanly to the pinned-layer-only behavior (syncLayer still positions).
      layer.removeAttribute('popover')
      layer.style.cssText = 'position:fixed;top:0;left:0;width:0;height:0;'
    }
  }
  syncLayer(layer)

  // Re-pin whenever an overlay is inserted — it may open after the page scrolled or
  // the layout shifted (the layer isn't synced while empty). syncLayer only mutates
  // the layer's own style, so it never re-triggers this childList observer. The
  // observer is referenced only via the WeakMap, so it is disconnected when the layer
  // detaches (in syncActiveLayers) and otherwise GC'd with the layer.
  const observer = new MutationObserver((records) => {
    // S2: this layer serves exactly ONE overlay (one Portal instance), so its
    // `__wippyAnchorName` — the trigger anchor-name stamped by `setupOverlayLayer` — is unambiguous.
    // Anchor the overlay when it teleports in; release its style observer when it leaves.
    const anchorName = (layer as LayerWithAnchor).__wippyAnchorName
    for (const rec of records) {
      if (anchorName) {
        for (const node of Array.from(rec.addedNodes)) {
          if (node instanceof HTMLElement)
            applyAnchor(node, anchorName)
        }
      }
      for (const node of Array.from(rec.removedNodes)) {
        if (node instanceof HTMLElement)
          releaseAnchor(node)
      }
    }
    if (layer.isConnected && layer.childElementCount > 0)
      syncLayer(layer)
  })
  observer.observe(layer, { childList: true })
  layerObservers.set(layer, observer)

  activeLayers.add(layer)
  if (!viewportListenersAttached) {
    viewportListenersAttached = true
    // Capture phase so a scrolling ancestor (not just the window) also triggers a
    // resync; passive since we never preventDefault. One pair total, for all layers.
    window.addEventListener('scroll', onViewportChange, { capture: true, passive: true })
    window.addEventListener('resize', onViewportChange, { passive: true })
  }
  return layer
}

/**
 * PrimeVue's shared `primevue/portal` is an Options-API component object (a singleton
 * shared by every overlay). We rewrite the render-relevant options on it in place.
 */
interface PortalOptions {
  computed?: Record<string, (this: PortalInstance) => unknown>
  data?: (this: PortalInstance) => Record<string, unknown>
  mounted?: (this: PortalInstance) => void
  unmounted?: (this: PortalInstance) => void
  render?: (this: PortalInstance) => VNode
}

interface PortalInstance {
  /** The Portal's `$el` — a comment `Node` (placeholder vnode) before teleport. */
  $el: Node | null
  $slots: Record<string, unknown>
  disabled?: boolean
  /** `'self'` (inline), `'body'`/null/undefined (teleport), or an explicit target. */
  appendTo?: unknown
  inline: boolean
  mounted: boolean
  /** The shadow root this overlay lives in (captured once on mount), or null. */
  hostRoot: ShadowRoot | null
  /** This overlay's OWN layer div (one per Portal instance); null in light DOM or while inline. */
  layer: HTMLElement | null
  /** Unique `anchor-name` wired onto this overlay's trigger for S2, or null. */
  anchorName: string | null
  /** The trigger element the anchor-name was stamped on (to clear it on teardown). */
  anchorTrigger: HTMLElement | null
  resolvedTarget: Element | string | null
  /** Vue instance watcher — used to react to `inline` toggling after mount. */
  $watch: (source: string, cb: (value: boolean) => void) => () => void
}

/** Create this overlay's layer and wire its S2 anchor. Idempotent per instance. */
function setupOverlayLayer(inst: PortalInstance): void {
  if (!inst.hostRoot || inst.layer)
    return
  // Eager: the layer is promoted to the top layer BEFORE the overlay opens, so PrimeVue
  // never measures a not-yet-promoted box.
  inst.layer = createLayer(inst.hostRoot)
  // S2: stamp a unique `anchor-name` on the trigger (the placeholder's parent is the
  // component root the self-anchored families align to) and hand it to this layer.
  if (supportsAnchor()) {
    const trigger = inst.$el ? (inst.$el as Node).parentElement : null
    if (trigger) {
      inst.anchorName = `--wippy-a-${++anchorSeq}`
      inst.anchorTrigger = trigger
      trigger.style.setProperty('anchor-name', inst.anchorName)
      ;(inst.layer as LayerWithAnchor).__wippyAnchorName = inst.anchorName
    }
  }
}

/** Remove this overlay's layer and undo its S2 wiring (on unmount or a switch to inline). */
function teardownOverlayLayer(inst: PortalInstance): void {
  if (inst.anchorTrigger) {
    inst.anchorTrigger.style.removeProperty('anchor-name')
    inst.anchorTrigger = null
  }
  inst.anchorName = null
  if (inst.layer) {
    for (const child of Array.from(inst.layer.children)) {
      if (child instanceof HTMLElement)
        releaseAnchor(child)
    }
    activeLayers.delete(inst.layer)
    layerObservers.get(inst.layer)?.disconnect()
    inst.layer.remove()
    inst.layer = null
  }
}

interface PrimeVueMenuOptions {
  methods?: {
    bindOutsideClickListener?: (this: PrimeVueMenuInstance) => void
  }
}

interface PrimeVueMenuInstance {
  container: HTMLElement | null
  target: HTMLElement | null
  outsideClickListener: ((event: MouseEvent) => void) | null
  overlayVisible: boolean
  popup: boolean
  focusedOptionIndex: string | number
  hide: () => void
}

let menuOutsideClickPatched = false

/**
 * PrimeVue 4.5.5 Menu still tests document-capture clicks with `event.target`.
 * At the document boundary, a click from inside a shadow root is retargeted to
 * the shadow host, so Menu mistakes its own teleported panel for an outside
 * click and hides before an input or menu item can handle the event.
 *
 * Select already uses `event.composedPath()`. Apply the same rule to Menu while
 * preserving its popup/inline behavior. Menu is imported and patched by this
 * plugin so consumers only need to install `PrimeVuePlugin`.
 */
function patchMenuOutsideClick(): void {
  if (menuOutsideClickPatched)
    return

  const menu = Menu as unknown as PrimeVueMenuOptions
  if (!menu.methods || typeof menu.methods.bindOutsideClickListener !== 'function')
    return

  menu.methods.bindOutsideClickListener = function (this: PrimeVueMenuInstance) {
    if (this.outsideClickListener)
      return

    this.outsideClickListener = (event: MouseEvent) => {
      const path = event.composedPath()
      const isOutsideContainer = this.container && !path.includes(this.container)
      const isOutsideTarget = !(this.target && path.includes(this.target))

      if (this.overlayVisible && isOutsideContainer && isOutsideTarget)
        this.hide()
      else if (!this.popup && isOutsideContainer && isOutsideTarget)
        this.focusedOptionIndex = -1
    }
    document.addEventListener('click', this.outsideClickListener, true)
  }

  menuOutsideClickPatched = true
}

interface PrimeVueContextMenuOptions {
  methods?: {
    bindOutsideClickListener?: (this: PrimeVueContextMenuInstance) => void
  }
}

interface PrimeVueContextMenuInstance {
  container: HTMLElement | null
  target: HTMLElement | null
  outsideClickListener: ((event: MouseEvent) => void) | null
  visible: boolean
  hide: () => void
}

let contextMenuOutsideClickPatched = false

/**
 * ContextMenu carries the same `event.target` bug as Menu and is NOT covered by
 * the patch above — they are separate components with their own copy of the
 * listener.
 *
 * The failure inside a shadow root is worse here than for Menu: the retargeted
 * click makes `container.contains(target)` false, so `hide()` runs in the
 * CAPTURE phase — before the menu item's own click handler. The command still
 * fires (Vue re-renders on a microtask, so the synchronous dispatch completes),
 * but the menu flickers shut on every interaction and submenus never stay open.
 *
 * ContextMenu's listener differs from Menu's: it has no popup/inline split and
 * no `focusedOptionIndex` reset, and it gates the target test on `visible`.
 * Keep that shape and change only how membership is tested.
 */
function patchContextMenuOutsideClick(): void {
  if (contextMenuOutsideClickPatched)
    return

  const contextMenu = ContextMenu as unknown as PrimeVueContextMenuOptions
  if (!contextMenu.methods || typeof contextMenu.methods.bindOutsideClickListener !== 'function')
    return

  contextMenu.methods.bindOutsideClickListener = function (this: PrimeVueContextMenuInstance) {
    if (this.outsideClickListener)
      return

    this.outsideClickListener = (event: MouseEvent) => {
      const path = event.composedPath()
      // `path.includes(target)` covers both upstream branches at once —
      // `target === event.target` and `target.contains(event.target)`.
      const isOutsideContainer = this.container && !path.includes(this.container)
      const isOutsideTarget = this.visible ? !(this.target && path.includes(this.target)) : true

      if (isOutsideContainer && isOutsideTarget)
        this.hide()
    }
    document.addEventListener('click', this.outsideClickListener, true)
  }

  contextMenuOutsideClickPatched = true
}

let patched = false

/**
 * Make PrimeVue overlays render inside the shadow root — unclipped and correctly
 * positioned — by default, without any per-component `appendTo`.
 *
 * PrimeVue 4 has no global `appendTo` config, and the `@primeuix/utils` positioning
 * helpers are immutable ESM bindings. But every overlay teleports through the ONE
 * shared `primevue/portal`, whose options object is a mutable singleton. We rewrite it
 * so the DEFAULT `appendTo` (`'body'`, or null/undefined) teleports to a per-overlay
 * layer ({@link createLayer}) that is measured-and-pinned to true viewport origin
 * ({@link syncLayer}) instead of `document.body`.
 *
 * Because `appendTo` is then not `'self'`, PrimeVue positions with `absolutePosition`
 * (document-origin coords), which the pinned layer matches — so overlays are NOT
 * clipped by a scrolling Dialog/Drawer body and land at the trigger, even under a
 * transformed/filtered ancestor or a scrolled window. `'self'` keeps its inline
 * semantics (explicit opt-in); outside a shadow root everything falls back to
 * `document.body`. `resolvedTarget` is a computed, so a reactive `appendTo` is honored.
 *
 * Runs once at plugin install (before the first overlay renders); the guard makes
 * repeat installs safe.
 */
export function patchOverlayPortal(): void {
  if (patched)
    return
  patched = true

  const portal = Portal as unknown as PortalOptions

  portal.computed = portal.computed || {}
  portal.computed.inline = function (this: PortalInstance) {
    return Boolean(this.disabled) || this.appendTo === 'self'
  }
  // Reactive to `appendTo`: the default ('body'/null) resolves to this overlay's own
  // layer (or document.body in light DOM); an explicit target passes through.
  portal.computed.resolvedTarget = function (this: PortalInstance) {
    if (this.appendTo == null || this.appendTo === 'body')
      return this.hostRoot ? this.layer : document.body
    return this.appendTo as Element | string
  }

  portal.data = function (this: PortalInstance) {
    return { mounted: false, hostRoot: null, layer: null, anchorName: null, anchorTrigger: null }
  }

  portal.mounted = function (this: PortalInstance) {
    // Match upstream Portal: teleport is client-only. Guards DOM access below
    // (createLayer → createElement) if this ever runs without a document.
    if (!isClient())
      return
    // `$el` here is the placeholder comment node — capture its shadow root once.
    this.hostRoot = shadowRootOf(this.$el)
    this.mounted = true
    // Light DOM (no shadow root) always teleports to document.body — no layer, ever.
    if (!this.hostRoot)
      return
    // Create the layer now if this overlay teleports; skip it while inline
    // (`appendTo:'self'`/`disabled`) so nothing is allocated unused.
    if (!this.inline)
      setupOverlayLayer(this)
    // `inline` is a computed over reactive props, and consumers DO flip `appendTo`
    // ('body'↔'self') after mount (e.g. `use-shadow-append-to`). Mirror the layer
    // lifecycle on that toggle: a switch to inline tears down the now-unused layer
    // instead of orphaning it; a switch back re-creates it (else `resolvedTarget` would
    // fall back to document.body, breaking out of the shadow root). Auto-cleaned on unmount.
    this.$watch('inline', (nowInline) => {
      if (nowInline)
        teardownOverlayLayer(this)
      else
        setupOverlayLayer(this)
    })
  }

  portal.render = function (this: PortalInstance) {
    // The inline / teleport / not-yet-mounted branches return different vnode TYPES
    // (slot fragment vs Teleport vs comment), so Vue replaces (never patches) across them
    // if `inline` toggles reactively; the `key`s mirror upstream Portal's for parity.
    if (this.inline)
      return renderSlot(this.$slots as never, 'default', { key: 0 }) as unknown as VNode
    if (!this.mounted)
      return createCommentVNode('', true)
    // Teleport the overlay AS-IS, a direct child of this overlay's own layer. Its
    // anchor-name rides on the layer (set by `setupOverlayLayer`), so the observer anchors
    // it — no per-render vnode surgery, so PrimeVue's overlay markup is untouched.
    return h(Teleport, { key: 1, to: this.resolvedTarget || document.body } as never, [
      renderSlot(this.$slots as never, 'default'),
    ])
  }

  portal.unmounted = function (this: PortalInstance) {
    // Each overlay OWNS its layer, so it removes it (and undoes its S2 wiring) on unmount
    // — no orphaned 0×0 popovers, observers, listeners, or stale `anchor-name` across
    // mount/unmount cycles. (The old shared per-root layer detached with the shadow root.)
    teardownOverlayLayer(this)
  }
}

export const PrimeVuePlugin = {
  install: (app: App) => {
    patchMenuOutsideClick()
    patchContextMenuOutsideClick()
    patchOverlayPortal()
    app.use(PrimeVue, { theme: 'none' })
  },
}

export default PrimeVuePlugin
